import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useLocation } from 'react-router-dom';
import {
    Card,
    Stack,
    Typography,
    Divider,
    IconButton,
    Box,
    TablePagination,
} from '@mui/material';
import dayjs from 'dayjs';

import JsPDF from 'jspdf';
import 'jspdf-autotable';
import DownloadIcon from '@mui/icons-material/Download';
import ClearIcon from '@mui/icons-material/Clear';
import RefreshIcon from '@mui/icons-material/Refresh';
import { axios } from '../../utils/axios';
import Scrollbar from '../../components/scrollbar';
import { useMyContext } from '../provider';
import useResponsive from '../../hooks/useResponsive';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';
import DateFormat from '../../components/dayjsFormat/DateFormat';

export default function MyTable() {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const [earningsReportList, setEarningsReportList] = useState([]);
    const [totalCount, setTotalCount] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
    const [search, setSearch] = useState(queryParams.get('search') || '');
    const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
    const { i18 } = useMyContext();
    const isMobile = useResponsive('down', 'sm');


    const [filters, setFilters] = useState({ bookingNo: '', propertyName: '', updatedAt: '' });
    const [isLoading, setIsLoading] = useState(true);

    const columns = [
        { accessorKey: 'bookingNo', id: 'bookingNo', header: i18?.ACCOUNTSTITLE?.BOOKING_NO||"Booking No", showFilter: true },
        { accessorKey: 'propertyCategoryDetails.category', header: i18?.ACCOUNTSTITLE?.PROPERTY_CATEGORY||'Property Category', id: "propertyCategory", showFilter: true },
        { accessorKey: 'listingDetails.propertyName', header: i18?.ACCOUNTSTITLE?.PROPERTY_NAME||'Property Name', id: "propertyName", showFilter: true },
        { accessorKey: 'providerDetails.fullname', header: i18?.ACCOUNTSTITLE?.PROVIDER_NAME||'Provider Name', id: "providerName", showFilter: true },
        { accessorKey: 'userDetails.fullname', header:  i18?.ACCOUNTSTITLE?.GUEST_NAME||'Guest Name', id: "userName", showFilter: true },
        {
            accessorKey: 'updatedAt', header: i18?.ACCOUNTSTITLE?.LAST_UPDATED||'Last Updated', showFilter: true,
            id: 'updatedAt',
            cell: info => DateFormat(info.getValue()),
        },
        { accessorKey: 'commission', header: i18?.ACCOUNTSTITLE?.COMMISSION||'Commission', showFilter: false },
        { accessorKey: 'tax', header: i18?.ACCOUNTSTITLE?.TAX||'Tax', showFilter: false },
        { accessorKey: 'fareAmount', header: i18?.ACCOUNTSTITLE?.FARE_AMOUNT||'Fare Amount', showFilter: false },
        { accessorKey: 'hostAmount', header: i18?.ACCOUNTSTITLE?.HOST_AMOUNT||'Host Amount', showFilter: false },
        { accessorKey: 'adminEarned', header: i18?.ACCOUNTSTITLE?.ADMIN_EARNED||'Admin Earned', showFilter: false },
        { accessorKey: 'refundAmount', header: i18?.ACCOUNTSTITLE?.REFUND_AMOUNT||'Refund Amount', showFilter: false },
        // { accessorKey: 'currencySymbol', header: 'Currency', showFilter: false },
        { accessorKey: 'currency', header: i18?.ACCOUNTSTITLE?.CURRENCY||'Currency', showFilter: false },
    
        // { accessorKey: 'paymentMode', header: 'Payment Mode', showFilter: false },
        {
            accessorKey: 'status',
            header: i18?.ACCOUNTSTITLE?.STATUS||'Status',
            id: 'Status',
            showFilter: false,
            cell: ({ row }) => (
                <span>{row?.original?.status}</span>
            )
        },
    ];    

    const fetchData = async () => {
        setIsLoading(true);
        try {
            let url = `module/admin/earningReport?_page=${page}&_limit=${rowsPerPage}`;

            if (search) url += `&search=${search}`;
            Object.entries(filters).forEach(([key, value]) => {
                if (value) url += `&${key}=${value}`;
            });

            const response = await axios.get(url);
            if (response.status === 200) {
                setEarningsReportList(response?.data?.data?.bookingData || []);
                setTotalCount(response?.data?.data?.totalCount || 0);
            }
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [page, rowsPerPage, search, filters]);

    const handleFilterChange = (filterKey, value) => {
        setFilters((prev) => ({ ...prev, [filterKey]: value }));
        setPage(1);
    };

    const handleDownload = () => {
    const doc = new JsPDF('landscape');
    doc.text('Earnings Report', 14, 10);
    // doc.addFileToVFS("Amiri-Regular.ttf");
    // doc.addFont("Amiri-Regular.ttf", "Amiri", "normal");
    // doc.setFont("Amiri");

    doc.autoTable({
        head: [
            columns.map(col => ({
                content: col.header,
                styles: { cellWidth: 'wrap' },
            }))
        ],
        body: earningsReportList.map(row =>
            columns.map(col => {
                
                const cellData = col.accessorKey.split('.').reduce((acc, key) => acc && acc[key] ? acc[key] : '---', row);

                if (col.accessorKey === 'updatedAt' && cellData !== '---') {
                    return dayjs(cellData).format('DD/MM/YYYY HH:mm:ss');
                }
                // if (col.accessorKey === 'currency' && cellData !== '---') {
                //     return cellData;
                // }

                return cellData || '---';
            })
        ),
        startY: 20,
        headStyles: { fillColor: [22, 160, 133], textColor: 255, fontSize: 10 },
        styles: { fontSize: 8, valign: 'middle' },
        columnStyles: {
            0: { cellWidth: 15 },
            1: { cellWidth: 20 },
            2: { cellWidth: 20 },
            3: { cellWidth: 20 },
            4: { cellWidth: 20 },
            5: { cellWidth: 25 },
            6: { cellWidth: 20 },
            7: { cellWidth: 15 },
            8: { cellWidth: 20 },
            9: { cellWidth: 20 },
            10: { cellWidth: 20 },
            11: { cellWidth: 20 },
            12: { cellWidth: 15 },
        },
        tableWidth: 'auto',
    });

    doc.save('FilteredEarningsReport.pdf');
};

    const handleClearData = () => {
        setFilters({ bookingNo: '', propertyName: '', updatedAt: '' });
        setSearch('');
        setPage(1);
    };

    const handleRefresh = () => {
        fetchData();
    };

    const handleChangePage = (event, newpage) => {
        setPage(newpage + 1);
    };


    const handleChangeRowsPerPage = (event) => {
        setPage(1);
        setRowsPerPage(parseInt(event.target.value, 10));
    };

    return (
        <>
            <Card>
                <Helmet>
                    <title>Earnings Report</title>
                </Helmet>

                <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ p: 2 }}>
                    <Typography variant="h6">{i18?.ACCOUNTSTITLE?.EARNINGS_REPORT|| "Earnings Report"}</Typography>

                    <Stack direction="row" spacing={1}>
                        <IconButton color="primary" onClick={handleDownload}>
                            <DownloadIcon />
                        </IconButton>
                        <IconButton color="default" onClick={handleClearData}>
                            <ClearIcon />
                        </IconButton>
                        <IconButton color="default" onClick={handleRefresh}>
                            <RefreshIcon />
                        </IconButton>
                    </Stack>
                </Stack>

                <Divider />

                <Box sx={{ p: 2 }}>
                    <Scrollbar>
                        <TanstackTableV8
                            data={earningsReportList}
                            columns={columns}
                            filters={filters}
                            isLoading={isLoading}
                            onFilterChange={handleFilterChange}
                        />
                    </Scrollbar>
                </Box>
            </Card>
            <TablePagination
                rowsPerPageOptions={[5, 10, 25]}
                component="div"
                count={totalCount || '0'}
                rowsPerPage={rowsPerPage}
                page={page - 1}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                sx={{
                    '.MuiTablePagination-selectLabel': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-displayedRows': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-actions': {
                        marginBottom: '6px',
                    }
                }}
            />
        </>
    );
}